package com.tuap.backend.auth;
import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.UserConsentDAO;
@Service public class ConsentService { private final UserConsentDAO dao; private final String terms; private final String privacy; public ConsentService(UserConsentDAO d,@Value("${app.legal.terms-version:1.0}") String t,@Value("${app.legal.privacy-version:1.0}") String p){dao=d;terms=t;privacy=p;}
 public void recordRegistration(AuthenticatedUser u,boolean termsAccepted,boolean privacyAccepted,boolean marketing){ if(!termsAccepted)throw new ConsentRequiredException("TERMS_NOT_ACCEPTED");if(!privacyAccepted)throw new ConsentRequiredException("PRIVACY_NOT_ACCEPTED");Instant now=Instant.now();dao.saveAll(List.of(new UserConsent(u.userId(),u.role(),ConsentType.TERMS_OF_SERVICE,terms,true,now),new UserConsent(u.userId(),u.role(),ConsentType.PRIVACY_POLICY,privacy,true,now),new UserConsent(u.userId(),u.role(),ConsentType.MARKETING,terms,marketing,now))); }
 public Map<String,Object> status(AuthenticatedUser u){Map<ConsentType,UserConsent> m=new EnumMap<>(ConsentType.class);dao.findByUserIdAndRole(u.userId(),u.role()).forEach(c->m.put(c.getType(),c));return Map.of("terms",view(m.get(ConsentType.TERMS_OF_SERVICE)),"privacy",view(m.get(ConsentType.PRIVACY_POLICY)),"marketing",view(m.get(ConsentType.MARKETING)));}
 public void marketing(AuthenticatedUser u,boolean accepted){Instant now=Instant.now();UserConsent c=dao.findByUserIdAndRoleAndType(u.userId(),u.role(),ConsentType.MARKETING).orElseGet(()->new UserConsent(u.userId(),u.role(),ConsentType.MARKETING,terms,accepted,now));c.update(accepted,terms,now);dao.save(c);}
 public boolean requiresUpdatedConsent(AuthenticatedUser u){return requiresCurrent(u,ConsentType.TERMS_OF_SERVICE,terms)||requiresCurrent(u,ConsentType.PRIVACY_POLICY,privacy);}
 private boolean requiresCurrent(AuthenticatedUser u,ConsentType type,String version){return dao.findByUserIdAndRoleAndType(u.userId(),u.role(),type).map(c->!c.isAccepted()||!version.equals(c.getVersion())).orElse(true);}
 private Map<String,Object> view(UserConsent c){return c==null?Map.of("status","LEGACY_MISSING"):Map.of("accepted",c.isAccepted(),"version",c.getVersion(),"acceptedAt",Optional.ofNullable(c.getAcceptedAt()).map(Object::toString).orElse(""),"withdrawnAt",Optional.ofNullable(c.getWithdrawnAt()).map(Object::toString).orElse(""));} }
